style.css:
:root {
  color-scheme: light;
  --paper:#eef0f2;
  --surface:#fff;
  --ink:#1e2630;
  --muted:#606d7a;
  --line:#d4dbe1;
  --rail:#232c35;
  --blue:#315d79;
  --olive:#315d79;
  font-family:"Segoe UI Variable Text","Segoe UI",Arial,sans-serif;
}
*{box-sizing:border-box}
body{margin:0;min-width:320px;background:var(--paper);color:var(--ink);font:14px/1.5 "Segoe UI Variable Text","Segoe UI",Arial,sans-serif}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer}button:disabled{opacity:.45;cursor:default}a{color:inherit}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #5288ac;outline-offset:3px}
[hidden]{display:none!important}
.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.sidebar{position:fixed;inset:0 auto 0 0;width:200px;padding:26px 16px;background:var(--rail);color:#f5f7f9;display:flex;flex-direction:column;overflow-y:auto}
.wordmark{font:600 25px/1.2 Bahnschrift,"Arial Narrow",sans-serif;letter-spacing:-.9px;text-decoration:none}
.wordmark-mark{color:#a6bbca;margin-left:3px}
.brand-caption{color:#b6c1ca;font-size:12px;margin:6px 0 30px}
nav{display:grid;gap:4px}
nav button{display:flex;justify-content:space-between;align-items:center;gap:10px;text-align:left;border:0;border-radius:5px;padding:10px;background:transparent;color:#dce3e9;font-size:13px;min-height:42px}
nav button:hover{background:#303c47}nav button.active{background:#e4ebf1;color:#202e39;font-weight:650}
nav button span:last-child{font-size:11px;font-variant-numeric:tabular-nums;opacity:.75}
.more-views{margin-top:15px}
.more-views summary{font-size:12px;color:#bdc9d3;padding:9px 10px;cursor:pointer;border-top:1px solid #44515d}
.more-views nav{margin-top:6px}
.more-views:has(button.active)>summary{color:white}
.fit-card{border-top:1px solid #44515d;margin-top:22px;padding:16px 10px 0}
.fit-card h3{font-size:12px;font-weight:600;margin:0 0 6px}
.fit-card p{font-size:12px;line-height:1.8;color:#bec9d3;margin:0}
.sidebar-footer{font-size:11px;color:#bec9d3;margin-top:auto;padding:26px 10px 0}
.dot{display:inline-block;width:5px;height:5px;background:#b1c7d5;border-radius:50%;margin-right:6px}
main{margin-left:200px;padding:0 28px;max-width:1900px}
.intro{padding:25px 0 20px;display:flex;justify-content:space-between;align-items:flex-start;gap:20px}
h1{font:500 29px/1.2 Bahnschrift,"Arial Narrow",sans-serif;letter-spacing:-.65px;margin:0}
#listing-total{display:inline-block;font:400 14px "Segoe UI",sans-serif;letter-spacing:0;color:var(--muted);margin-left:8px;vertical-align:middle}
#view-description{font-size:13px;line-height:1.6;color:var(--muted);margin:7px 0 0;max-width:74ch}
.subtle,.filter-toggle,.details-button{border:1px solid var(--line);border-radius:5px;background:var(--surface);padding:9px 13px;font-size:12px;min-height:40px;white-space:nowrap}
.subtle:hover,.details-button:hover{border-color:var(--blue);color:var(--blue)}
.text-button{border:0;background:none;padding:6px 0;font-size:12px;color:var(--muted);text-decoration:underline;text-underline-offset:3px}
.collection-tools{padding-bottom:14px;border-bottom:1px solid var(--line)}
.filter-bar{display:grid;grid-template-columns:minmax(190px,1fr) minmax(130px,170px) minmax(105px,135px) auto;gap:10px;align-items:center}
.collection-tools label{display:flex;flex-direction:column;gap:5px;min-width:0}
.collection-tools label>span{font-size:11px;color:var(--muted)}
.collection-tools input,.collection-tools select,#sort{border:1px solid var(--line);border-radius:5px;background:var(--surface);padding:10px 11px;font-size:13px;min-height:41px;min-width:0;width:100%}
.search input{padding-left:14px}
.filter-toggle{display:flex;align-items:center;justify-content:center;gap:8px;min-height:41px}
.filter-toggle[aria-expanded=true]{background:var(--rail);border-color:var(--rail);color:white}
#filter-count{background:var(--blue);color:white;font-size:11px;border-radius:10px;min-width:18px;padding:0 4px}
.filter-chevron{font-size:15px;line-height:1}
.advanced-filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding-top:16px;max-width:900px}
.check-filter>span:last-child{display:flex;align-items:center;gap:7px;font-size:13px;color:var(--ink);min-height:41px}
.check-filter input{width:16px;min-height:16px;height:16px;accent-color:var(--blue);margin:0}
.result-strip{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:14px 0 7px}
#result-count{font-size:12px;color:var(--muted);margin:0}
.sort-tools{display:flex;align-items:center;gap:10px}
.sort-tools label{font-size:12px;white-space:nowrap;color:var(--muted)}
#sort{font-size:12px;min-height:34px;padding:6px 9px;width:195px;background:transparent}
.sort-tools .text-button{font-size:11px;white-space:nowrap}
.browse-hint{font-size:12px;color:var(--muted);margin:0 0 17px}
.notice{background:#fff8e8;border-left:3px solid #a47c31;font-size:12px;color:#6f562b;padding:10px 13px;margin-bottom:18px}
.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:30px 20px;align-items:stretch}
.card{min-width:0;display:flex;flex-direction:column}
.card-visual{position:relative;background:#e4e8eb;border:1px solid #d9dfe5;border-radius:7px;overflow:hidden}
.image-link{display:block;width:100%;padding:0;border:0;background:none;text-decoration:none;color:var(--ink)}
.image-link:focus-visible{outline-offset:-4px}
.photo{aspect-ratio:4/5;position:relative;display:grid;place-items:center;overflow:hidden;background:#f7f8f9}
.photo img{display:block;width:100%;height:100%;object-fit:contain}
.photo[data-photo-state=loading]::after{content:"Loading photo…";position:absolute;inset:auto 0 45%;text-align:center;font-size:12px;color:var(--muted);pointer-events:none}
.photo[data-photo-state=unavailable]{background:#e5eaf0}
.photo-fallback{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:28px;text-align:center}
.photo-fallback strong{font:500 23px Bahnschrift,"Arial Narrow",sans-serif;color:#3f5362}
.photo-reason{font-size:13px;color:#536576}
.photo-fallback small{font-size:12px;text-decoration:underline;text-underline-offset:3px;color:var(--blue);max-width:24ch}
.image-open{position:absolute;bottom:10px;right:10px;display:flex;gap:12px;align-items:center;min-height:32px;background:#fffefc;color:#25394a;border:1px solid #d6dee5;border-radius:4px;padding:5px 9px;font-size:11px;font-weight:600}
.image-link:hover .image-open{background:var(--blue);border-color:var(--blue);color:white}
.evidence-badge{font-size:10px;line-height:1.4;background:#fffdf8f5;color:#644f30;padding:5px 8px;border-radius:4px}
.card-visual>.evidence-badge{position:absolute;left:10px;top:10px;max-width:calc(100% - 62px);pointer-events:none;box-shadow:0 1px 4px #13233308}
.evidence-badge.search-lead{background:#e8edf4f5;color:#3c5367}
.save-icon{position:absolute;right:9px;top:9px;width:34px;height:34px;display:grid;place-items:center;border:1px solid #d6dee5;border-radius:5px;background:#fffefcf5;line-height:1;font-size:22px;color:#3d505f}
.save-icon.is-saved{color:#315d79;background:#e4edf4}
.photo-count{position:absolute;bottom:15px;left:12px;background:#fffffff0;font-size:10px;color:#536271;padding:3px 6px;border-radius:3px;pointer-events:none}
.card-body{padding:12px 1px 0;display:flex;flex-direction:column;flex:1}
.card-kicker{display:flex;justify-content:space-between;align-items:baseline;gap:10px;font-size:13px;font-weight:650}
.size-tag{font-size:11px;font-weight:500;line-height:1.2;color:#445666;border:1px solid #c7d2db;padding:3px 6px;max-width:50%;overflow-wrap:anywhere}
.card-title{font-size:16px;line-height:1.35;font-weight:500;margin:6px 0 7px;min-height:43px}
.title-link{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-decoration:none;text-align:left;border:0;padding:0;background:none;width:100%;font:inherit;color:var(--ink)}
.title-link:hover{text-decoration:underline;text-underline-offset:3px}
.card-price{font-size:17px;line-height:1.4;font-weight:650;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.card-price small{display:inline;font-size:12px;font-weight:400;color:var(--muted);margin-left:9px}
.card-price .native-price{display:block;margin:2px 0 0;font-size:12px;line-height:1.5}
.card-price .conversion-note,.card-price .auction-price-kind{display:block;margin:3px 0 0;font-size:11px;line-height:1.5}
.price-caption{display:block;font-size:11px;font-weight:400;color:var(--muted)}
.price-caption:empty{display:none}
.condition{font-size:12px;line-height:1.5;margin:6px 0 0;color:var(--muted);display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden}
.editorial-preview{font-size:12px;line-height:1.55;color:#435666;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:9px 0 0}
.card-caution{font-size:11px;color:#7d5a23;line-height:1.5;margin:8px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.card-primary{display:flex;align-items:stretch;gap:8px;margin-top:auto;padding-top:13px}
.original-listing{display:flex;align-items:center;justify-content:space-between;gap:16px;background:var(--blue);border:1px solid var(--blue);color:white;border-radius:5px;padding:9px 12px;min-height:39px;font-size:12px;font-weight:600;text-decoration:none}
.original-listing:hover{background:#244b64;border-color:#244b64}
.card-primary>.original-listing{flex:1}
.details-button{background:transparent;min-height:39px}
.source-missing{font-size:12px;color:var(--muted);align-self:center}
.card-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding:10px 0 11px;font-size:11px}
.card-bottom label{display:flex;align-items:center;gap:7px;color:var(--muted);cursor:pointer;min-height:26px}
.card-bottom input{width:14px;height:14px;accent-color:var(--blue);margin:0}
.review-status{font-size:10px;color:var(--blue)}
.card-source{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:42%}
.match-score{border:0;padding:4px 0;background:none;text-align:left;font-size:11px;color:var(--muted);white-space:nowrap}
.score-caption{margin-right:3px}.score-number{font-size:13px;font-weight:650;color:var(--ink);font-variant-numeric:tabular-nums}
.score-number small{font-size:10px;font-weight:400;color:var(--muted);margin-left:1px}
.match-score:hover{text-decoration:underline;text-underline-offset:3px}.match-score.qualified .score-number{color:var(--blue)}
.empty{grid-column:1/-1;min-height:280px;border:1px dashed #b9c5d0;background:#f8fafb;padding:42px 24px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}
.empty h2{font-size:22px;font-weight:500;margin:0 0 8px}.empty p{color:var(--muted);margin:0 0 18px}
.empty button{border:1px solid var(--blue);border-radius:5px;background:white;color:var(--blue);padding:10px 14px}
.load-more-wrap{display:flex;justify-content:center;padding:30px 0 0}
.main-footer{padding:20px 0 28px;margin-top:16px;font-size:11px;color:var(--muted)}
#coverage{font-size:12px;color:var(--muted);margin-top:30px;border-top:1px solid var(--line);padding-top:14px}
#coverage summary{cursor:pointer}#coverage-content{columns:2 300px}#coverage-content p{break-inside:avoid}
.compare-tray{position:fixed;bottom:18px;left:calc(50% + 100px);transform:translateX(-50%);display:flex;align-items:center;gap:15px;z-index:5;padding:12px 16px;border-radius:7px;background:var(--rail);color:white;box-shadow:0 5px 25px #1b2b3a25;font-size:12px;white-space:nowrap}
.compare-tray button{border:0;border-radius:4px;padding:9px 12px;background:#e8eff4;color:var(--ink)}
.compare-tray .tray-clear{padding:8px 0;background:transparent;color:white}
dialog{padding:0;border:1px solid #aab7c2;border-radius:9px;background:#f8fafb;color:var(--ink);width:94vw;max-width:1100px;max-height:92dvh}
dialog::backdrop{background:#152535a6}
.close{position:sticky;float:right;top:12px;margin:12px 12px -48px 0;width:36px;height:36px;border:1px solid var(--line);border-radius:5px;background:#fff;font-size:25px;line-height:1;z-index:4}
#detail-content{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.08fr)}
.detail-gallery{padding:24px;background:#e9eef2}
.detail-gallery .photo{border-radius:5px}
.thumbnails{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
.thumbnails button{width:58px;padding:0;border:2px solid transparent;border-radius:4px;background:none;overflow:hidden}
.thumbnails button.active{border-color:var(--blue)}
.thumbnails .photo{aspect-ratio:4/5}
.thumbnail-photo .photo-fallback{padding:3px}
.thumbnail-photo .photo-fallback strong,.thumbnail-photo .photo-fallback small{display:none}
.thumbnail-photo .photo-reason{font-size:8px;line-height:1.3}
.thumbnail-photo[data-photo-state=loading]::after{content:"…"}
.image-credit{font-size:11px;line-height:1.7;color:var(--muted);margin:12px 0 0}
.image-credit a{color:var(--blue);text-underline-offset:3px;display:block}
.detail-copy{padding:38px 28px 28px}
.eyebrow{font-size:12px;color:var(--muted);margin:0 0 8px}
.detail-copy h2{font:500 27px/1.2 Bahnschrift,"Arial Narrow",sans-serif;letter-spacing:-.3px;margin:0 0 20px;overflow-wrap:anywhere}
.detail-metrics{display:flex;justify-content:space-between;align-items:center;gap:16px}
.detail-price{font-size:24px;font-weight:650;text-align:right;font-variant-numeric:tabular-nums;line-height:1.4}
.detail-price small{display:block;font-size:12px;font-weight:400;color:var(--muted)}
.cost-summary{display:flex;flex-direction:column;gap:3px;font-size:17px;font-weight:600}
.cost-summary>span:first-child{font-size:12px;font-weight:400;color:var(--muted)}
.cost-summary small,.auction-cost small{display:block;font-size:12px;color:var(--muted);font-weight:400}
.auction-cost{font-size:14px;margin:12px 0}
.pills{display:flex;gap:8px;margin:16px 0}
.pills span{font-size:12px;border:1px solid #ccd6de;border-radius:4px;padding:4px 8px}
.detail-original{margin:16px 0;min-height:44px;font-size:14px}
.detail-copy section{margin-top:22px;padding-top:18px;border-top:1px solid var(--line)}
.detail-copy h3{font-size:14px;font-weight:600;margin:0 0 10px}
.detail-copy p,.detail-copy li{font-size:13px;line-height:1.65;color:#586775}
.detail-copy ul{padding-left:19px;margin:8px 0 16px}
.gate-note{font-size:12px;background:#edf1f5;padding:10px 12px;border-radius:4px}
.assessment{scroll-margin-top:20px}
.editorial-note{border-left:2px solid var(--blue);padding-left:12px}
.detail-copy .evidence-badge{display:inline-block}
.measurements{margin:0}
.measurements>div{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #e0e6eb;padding:7px 0;font-size:12px}
.measurements dt{color:var(--muted)}.measurements dd{margin:0;white-space:nowrap}
.measurements small{font-size:10px;color:var(--muted);margin-left:7px}
.source-link{font-size:13px;color:var(--blue);text-underline-offset:3px}
.fine-print{font-size:11px!important;color:var(--muted)}
.review-box label{font-size:13px}
.review-box textarea{width:100%;min-height:85px;resize:vertical;margin:8px 0;padding:11px;border:1px solid #bccbd6;border-radius:5px;background:white;font-size:13px}
.review-actions{display:flex;gap:8px;margin-bottom:10px}
.review-actions button{flex:1;border:1px solid #b9c9d4;border-radius:4px;background:white;min-height:40px;font-size:12px;padding:8px}
.review-actions button:first-child{background:var(--blue);border-color:var(--blue);color:white}
.inline-notice{padding:9px 12px;background:#e4edf4;border-radius:4px}
#comparison{padding:24px;max-width:1240px}
.compare-heading{display:flex;justify-content:space-between;gap:20px;align-items:start}
.compare-heading h2{font-size:24px;font-weight:500;margin:0 0 22px}
.compare-heading .close{margin:0;flex-shrink:0}
#comparison-content{overflow:auto}
#comparison table{border-collapse:collapse;width:100%;min-width:600px;table-layout:fixed;font-size:12px}
#comparison th,#comparison td{padding:12px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line);font-weight:400}
#comparison th:first-child{width:145px;font-size:11px;color:var(--muted)}
#comparison .photo{aspect-ratio:4/3;border-radius:5px;margin-bottom:14px}
#comparison h3{font-size:16px;font-weight:550;line-height:1.4;margin:0 0 12px}
#toast{position:fixed;bottom:24px;right:24px;z-index:20;max-width:min(420px,90vw);padding:13px 18px;border-radius:5px;background:var(--rail);color:white;font-size:13px}
@media(min-width:1600px){.grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:1150px){.sidebar{width:184px;padding:24px 12px}main{margin-left:184px;padding:0 22px}.grid{gap:26px 16px}.compare-tray{left:calc(50% + 92px)}}
@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.filter-bar{grid-template-columns:minmax(150px,1fr) 130px 100px auto}.sort-tools label{display:none}.result-strip{align-items:start}#sort{width:175px}.sort-tools{gap:8px}}
@media(max-width:750px){
 .sidebar{position:relative;inset:auto;width:auto;padding:15px 18px 0;overflow:visible;display:grid;grid-template-columns:1fr auto;gap:13px 12px}
 .wordmark{font-size:23px;align-self:center}.brand-caption,.fit-card,.sidebar-footer{display:none}
 .sidebar>nav{grid-column:1/-1;grid-row:2;display:flex;overflow:auto;gap:4px;padding:0 0 12px;scrollbar-width:thin}
 nav button{flex-shrink:0;min-height:36px;padding:8px 10px;font-size:12px}
 .more-views{grid-column:2;grid-row:1;margin:0;align-self:center}
 .more-views summary{font-size:12px;border:1px solid #617180;border-radius:4px;padding:6px 9px;min-height:34px;list-style:none}
 .more-views[open]>nav{position:absolute;right:18px;top:55px;z-index:10;display:grid;background:var(--rail);border:1px solid #536777;box-shadow:0 8px 24px #14253630;border-radius:7px;padding:8px;min-width:230px;margin:0}
 main{margin-left:0;padding:0 18px}.intro{padding:20px 0 15px;gap:14px}
 h1{font-size:26px}#view-description{font-size:12px;line-height:1.6;max-width:58ch}
 .grid{gap:26px 16px}.result-strip{flex-wrap:wrap;align-items:center;margin-top:12px}
 .compare-tray{left:50%;max-width:94vw;gap:11px}
 #detail-content{grid-template-columns:1fr}.detail-gallery{padding:20px}
 .detail-gallery #hero-photo .photo{height:380px;aspect-ratio:auto}
 .detail-copy{padding:26px 22px}.detail-copy h2{font-size:25px}
 dialog{width:96vw;max-height:94dvh}.close{top:10px}
}
@media(max-width:540px){
 .intro{padding:18px 0 15px}.intro .subtle{font-size:11px;padding:8px 10px;min-height:36px}
 h1{font-size:25px}#listing-total{font-size:13px;margin-left:5px}#view-description{max-width:31ch;margin-top:6px}
 .filter-bar{grid-template-columns:minmax(0,1fr) 88px;gap:9px}
 .search{grid-column:1;grid-row:1}.filter-toggle{grid-column:2;grid-row:1}
 .brand-filter,.size-filter{display:none!important}
 .collection-tools:has(#advanced-filters:not([hidden])) .brand-filter,.collection-tools:has(#advanced-filters:not([hidden])) .size-filter{display:flex!important;grid-row:2}
 .brand-filter{grid-column:1}.size-filter{grid-column:2}
 .advanced-filters{grid-template-columns:1fr 1fr;gap:12px 10px;padding-top:12px}
 .collection-tools input,.collection-tools select{min-height:43px;font-size:14px}
 .result-strip{gap:5px}.sort-tools{margin-left:auto}#sort{width:155px;max-width:100%;font-size:11px;min-height:33px}
 .sort-tools .text-button{font-size:10px}.sort-tools label{display:none}
 #result-count{font-size:11px;max-width:125px;line-height:1.4}
 .browse-hint{display:none}
 .grid{grid-template-columns:1fr;gap:28px}
 .card-visual .photo{aspect-ratio:4/5}.card-body{padding:13px 1px 0}
 .card-title{font-size:18px;min-height:0}.card-kicker{font-size:14px}.size-tag{font-size:12px}
 .card-price{font-size:20px}.card-price small{font-size:13px}.condition{font-size:13px}
 .editorial-preview{font-size:13px}.card-caution{font-size:12px}
 .card-primary .original-listing,.card-primary .details-button{min-height:44px;font-size:13px}
 .save-icon{width:38px;height:38px;font-size:24px}
 .evidence-badge{font-size:11px}.image-open{font-size:12px;min-height:35px}
 .card-bottom{font-size:12px}.match-score{font-size:12px}.score-number{font-size:14px}
 .compare-tray{font-size:10px;gap:10px;padding:10px}.compare-tray button{padding:9px}
 #comparison{padding:18px 12px}#comparison th:first-child{width:110px}
