app.js:
import { evidenceKind, filterCollection, isUnavailable, matchesCollectionView, paginateCollection, sortCollection } from './collection.js';
import { capturedImageUrls, createImageLoader } from './images.js';
import { originalListingUrl, publicUrl, sourceName } from './listing.js';
import { usdPrice, formatMoney } from './money.js';
const $ = (s) => document.querySelector(s);
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
const dollars = amount => formatMoney(amount, 'USD', {currencyDisplay:'symbol'});
const safeUrl = publicUrl;
const imageLoader = createImageLoader();
const date = (v) => v && Number.isFinite(Date.parse(v)) ? new Date(v).toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' }) : 'Not recorded';
const labels = { new:'Unreviewed', liked:'Saved', watching:'Watching', rejected:'Passed' };
let data, view = 'latest', selected = new Set(), activeId, saving = false, toastTimer, visibleCount = 48;
const views = {
  latest:['Latest crawl', 'New and revisited pieces from the last search. Check each stock label before buying.'],
  all:['All discoveries', 'Captured listings, including those below your match threshold.'],
  auctions:['Auction watch', 'Auction leads, with current bids kept separate from fixed prices. Ended auctions are hidden automatically; confirm the live bid and deadline at the source.'],
  qualified:['Shopping shortlist', 'Reviewed pieces that meet your fit, style and current stock requirements.'],
  stretch:['Exceptional Acronym', 'Selected secondhand Acronym above your ¥90,000 routine ceiling. These are stretch-budget research, not purchase recommendations; confirm fit, condition and total cost.'],
  liked:['Saved pieces', 'Listings you saved for later.'],
  watching:['Watchlist', 'Listings to revisit. Price and stock updates are manual.'],
  rejected:['Passed', 'Listings you passed on. You can reset any decision.'],
  added:['Added this week', 'Listings first seen in the last seven days.'],
  drops:['Price drops', 'Listings whose captured collection change is a price drop.'],
  review:['Needs checking', 'Listings marked for review.'],
  unavailable:['Unavailable', 'Listings reported unavailable or unavailable by the search index.'],
};
if (Object.hasOwn(views, location.hash.slice(1))) view = location.hash.slice(1);

function scoreSummary(r) {
  return `<button class="match-score ${r.qualified ? 'qualified' : ''}" data-score="${esc(r.candidate.id)}" aria-label="Explain match score ${r.score} out of 100 for ${esc(r.candidate.title)}"><span class="score-caption">Match</span> <span class="score-number">${r.score}<small>/100</small></span></button>`;
}

const sortLabels = { score:'Highest match scores first. Score reflects captured evidence, not a guarantee of fit.', 'score-asc':'Lowest match scores first.', price:'Lowest fixed listing prices first. Auctions and unknown prices last. Fees and shipping may be extra.', 'price-desc':'Highest fixed listing prices first. Auctions and unknown prices last. Fees and shipping may be extra.', rank:'Wanted models first, then match score with the existing deal adjustment.', recent:'Most recent captured availability timestamps first. These are not listing dates.', ending:'Earliest reported auction deadlines first. Unknown deadlines last. Confirm the deadline at the source.' };
sortLabels.editorial = 'Editorial picks first, then research, unreviewed and passes. Within each group, use the existing adjusted ranking score. This does not verify stock or fit.';
$('#sort').prepend(new Option('Editorial picks first', 'editorial'));
let hasSavedSort = false;
$('#sort').value = 'rank';
try { const saved = localStorage.getItem('fieldnotes.sort.v2'); if (Object.hasOwn(sortLabels, saved)) { $('#sort').value = saved; hasSavedSort = true; } } catch {}

function images(c) {
  return capturedImageUrls(c);
}

function photo(c, className = '', index = 0, eager = false, allowFallbacks = true) {
  const hasImage = images(c).length > 0;
  return `<div class="photo ${className}" data-photo-state="${hasImage ? 'loading' : 'unavailable'}"><img data-candidate-image="${esc(c.id)}" data-photo-index="${index}" data-allow-fallbacks="${allowFallbacks}" alt="${esc(c.brand + ' ' + c.title)}" loading="${eager ? 'eager' : 'lazy'}" decoding="async" referrerpolicy="no-referrer"><span class="photo-fallback" ${hasImage ? 'hidden' : ''}><strong>${esc(c.brand)}</strong><span class="photo-reason">No photo captured</span><small>Open the listing to see source photos</small></span></div>`;
}

function hydrateImages(scope) {
  scope.querySelectorAll('[data-candidate-image]').forEach(img => {
    const c = item(img.dataset.candidateImage)?.candidate;
    if (!c) return;
    imageLoader.attach(img, c, {index:Number(img.dataset.photoIndex), allowFallbacks:img.dataset.allowFallbacks !== 'false', onState:({status,reason}) => {
      const frame = img.closest('.photo');
      frame.dataset.photoState = status;
      frame.querySelector('.photo-fallback').hidden = status !== 'unavailable';
      frame.querySelector('.photo-reason').textContent = reason === 'failed' ? 'Source photo could not load' : 'No photo captured';
    }});
  });
}

function listingAnchor(c, className = 'original-listing') {
  const link = originalListingUrl(c);
  return link ? `<a class="${className}" href="${esc(link)}" target="_blank" rel="noopener noreferrer" aria-label="Open original listing for ${esc(c.title)} on ${esc(sourceName(c))}"><span>Open listing</span><span aria-hidden="true">↗</span></a>` : '<span class="source-missing">Source link unavailable</span>';
}

function item(id) { return data.items.find(r => r.candidate.id === id); }
function isAuction(c) { return !!c.auction || c.dealEvidence?.saleType === 'auction'; }
function deadline(c) { return c.auction?.endsAt ? new Date(c.auction.endsAt).toLocaleString('en-US', {month:'short', day:'numeric', hour:'numeric', minute:'2-digit', timeZoneName:'short'}) : 'Deadline not confirmed'; }
function price(c) {
  const p = usdPrice(c, data.exchangeRates);
  const reference = p.kind === 'reference';
  const knownUsd = Number.isFinite(p.usd);
  const primary = reference ? 'Asking price unknown' : knownUsd ? `${p.estimated ? '≈ ' : ''}${dollars(p.usd)}` : p.amount ? 'USD unavailable' : 'Price unknown';
  const formatted = Number.isFinite(p.amount) && p.currency ? formatMoney(p.amount,p.currency) : p.originalText;
  const native = p.reason && knownUsd && p.originalText ? `${p.originalText} · captured ${formatted}` : formatted;
  const secondary = reference ? `Retail reference: ${knownUsd ? '≈ '+dollars(p.usd)+' / ' : ''}${native || ''}` : p.currency === 'USD' && knownUsd ? 'USD' : native;
  const auctionKind = p.kind === 'auction-bid' ? 'Reported bid' : p.kind === 'auction-buy-now' ? 'Buy now' : isAuction(c) ? 'Auction price unconfirmed' : null;
  return `<span class="usd-price">${esc(primary)}</span>${secondary ? `<small class="native-price">${esc(secondary)}</small>` : ''}${!knownUsd && p.conversionReason ? `<small class="conversion-note">${esc(p.conversionReason)}</small>` : ''}${auctionKind ? `<small class="auction-price-kind">${auctionKind} · Ends: ${esc(deadline(c))}</small>` : ''}`;
}
function plainPrice(c) {
  const p = usdPrice(c,data.exchangeRates);
  const formatted = Number.isFinite(p.amount) && p.currency ? formatMoney(p.amount,p.currency) : p.originalText;
  const original = p.reason && Number.isFinite(p.usd) && p.originalText ? `${p.originalText} · captured ${formatted}` : formatted;
  const converted = Number.isFinite(p.usd) ? `${p.estimated ? '≈ ' : ''}${dollars(p.usd)} USD` : 'USD unavailable';
  const kind = p.kind === 'auction-bid' ? 'Reported bid; ' : p.kind === 'auction-buy-now' ? 'Buy now; ' : p.kind === 'reference' ? 'Retail reference; asking price unknown; ' : '';
  return `${kind}${converted}${original && p.currency !== 'USD' ? ' / '+original : ''}`;
}
function priceAmount(amount,currency='JPY') { return price({priceOriginal:{amount,currency}}); }
function currencyNote() {
  return data.exchangeRates?.date ? `USD estimates use ECB reference rates from ${date(data.exchangeRates.date+'T12:00:00Z')}. Fees, shipping, tax and card conversion charges are extra.` : 'USD conversions use the saved exchange-rate estimate. Fees, shipping and tax are extra.';
}
function proxyLink(c) { const url = safeUrl(c.proxyUrl); return url && url !== safeUrl(c.url) ? `<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">View via FromJapan ↗</a>` : ''; }
function evidenceBadge(r) {
  const kind = evidenceKind(r);
  if (isAuction(r.candidate)) return '<span class="evidence-badge">Auction · confirm live status</span>';
  if (kind === 'search-index') return '<span class="evidence-badge search-lead">Search lead</span>';
  if (kind === 'stock-unconfirmed') return '<span class="evidence-badge">Stock unconfirmed</span>';
  return '<span class="evidence-badge">Item stock checked</span>';
}
function editorial(r, detailed = false) {
  const e = r.normalizedEditorialSummary;
  if (!e) return '';
  const label = {recommend:'Worth a look', research:'Research only', pass:'Not recommended'}[e.verdict];
  if (!detailed) return `<p class="editorial-preview" title="${esc(e.rationale)}">${esc(e.rationale)}</p>`;
  return `<section class="editorial-note"><h3>${esc(label)}</h3><p>${esc(e.rationale)}</p>${detailed ? `<p>${esc(e.valueAssessment)}</p>${e.limitations.length ? list(e.limitations) : ''}` : ''}</section>`;
}
function coverageText(crawl) {
  const workers = Array.isArray(crawl?.coverage?.workers) ? crawl.coverage.workers : [];
  if (!workers.length) return '';
  return workers.map(w => `<p>${esc(w.taskId ?? 'task')} · ${Number(w.listings ?? 0)} records · ${Number(Array.isArray(w.pagesRead) ? w.pagesRead.length : w.pagesRead ?? 0)} page observations${w.blocked?.length ? `<br><small>${w.blocked.map(b => esc(typeof b === 'string' ? b : [b.title, b.reason].filter(Boolean).join(': '))).join(' · ')}</small>` : ''}</p>`).join('');
}
function toast(message) {
  clearTimeout(toastTimer);
  // Native dialogs occupy a top layer above ordinary fixed-position toasts.
  if ($('#detail').open) {
    let notice = $('#detail .inline-notice');
    if (!notice) { notice = document.createElement('p'); notice.className = 'inline-notice'; notice.setAttribute('role', 'status'); $('#detail .review-actions').after(notice); }
    notice.textContent = message;
  } else { $('#toast').textContent = message; $('#toast').hidden = false; toastTimer = setTimeout(() => $('#toast').hidden = true, 4000); }
}
function list(values) { return `<ul>${values.map(v => `<li>${esc(v)}</li>`).join('')}</ul>`; }

async function load() {
  const res = await fetch('/fieldnotes/api/catalog');
  if (!res.ok) throw new Error((await res.json()).error || 'Unable to load collection');
  data = await res.json();
  const rateSource = safeUrl(data.exchangeRates?.source);
  $('#currency-note').innerHTML = `${esc(currencyNote())}${rateSource ? ` <a href="${esc(rateSource)}" target="_blank" rel="noopener noreferrer">Rate source ↗</a>` : ''}`;
  if (!hasSavedSort && data.profile.shopping?.requireEditorialReview) $('#sort').value = 'editorial';
  $('#crawl-summary').hidden = !data.crawl;
  if (data.crawl) {
    const latest = data.items.filter(r=>r.latestCapture && !isUnavailable(r));
    $('#crawl-notes').textContent = `${date(data.crawl.startedAt)} · ${latest.length} visible pieces · ${latest.filter(r=>r.qualified).length} shortlist · ${latest.filter(r=>isAuction(r.candidate)).length} auction leads.`;
  }
  $('#coverage').hidden = !data.crawl?.coverage?.workers?.length;
  $('#coverage-content').innerHTML = coverageText(data.crawl);
  selected = new Set([...selected].filter(id => item(id)));
  for (const key of ['brand', 'source', 'size']) {
    const el = $(`#${key}`), value = el.value;
    const values = [...new Set(data.items.map(r => r.candidate[key]))].sort();
    el.innerHTML = `<option value="">All ${key === 'brand' ? 'brands' : key === 'size' ? 'sizes' : 'sources'}</option>` + values.map(v => `<option value="${esc(v)}">${esc(v)}</option>`).join('');
    el.value = values.includes(value) ? value : '';
  }
  const p = data.profile.person ?? {};
  $('#fit-notes').textContent = `${p.chestInches ?? '—'}″ chest · ${p.waistInches?.min ?? '—'}–${p.waistInches?.max ?? '—'}″ waist. Tops ${(p.topSizes ?? []).join(' / ') || 'unspecified'}.`;
  render();
}

function render() {
  if (!data) return;
  const filters = { view, query: $('#search').value, brand: $('#brand').value, size: $('#size').value, source: $('#source').value, stock: $('#stock').value, evidence: $('#evidence').value, photosOnly: $('#photos-only').checked, maxPriceUsd: $('#budget').value, exchangeRates:data.exchangeRates, minScore: $('#min-score').value };
  const filtered = filterCollection(data.items, filters);
  const rows = sortCollection(filtered, $('#sort').value, data.exchangeRates);
  const page = paginateCollection(rows, visibleCount);
  $('#view-title').innerHTML = `${esc(views[view][0])} <span id="listing-total">${filtered.length}</span>`; $('#view-description').textContent = views[view][1];
  $('#sort-explanation').textContent = sortLabels[$('#sort').value];
  for (const key of Object.keys(views)) {
    $(`#count-${key}`).textContent = data.items.filter(r => matchesCollectionView(r, key) && (key === 'unavailable' || !isUnavailable(r))).length;
    $(`[data-view="${key}"]`).classList.toggle('active', key === view);
    $(`[data-view="${key}"]`).setAttribute('aria-current', key === view ? 'page' : 'false');
  }
  const sourceCount = new Set(filtered.map(r => r.candidate.source)).size;
  $('#result-count').textContent = `${filtered.length} ${filtered.length === 1 ? 'piece' : 'pieces'}${view === 'all' ? ' in your collection' : ' in this view'} · ${sourceCount} ${sourceCount === 1 ? 'source' : 'sources'}`;
  $('#notice').hidden = !!data.items.some(r => r.qualified) || view !== 'all';
  $('#notice').textContent = '0 strong matches. Each listing below shows its score and the evidence that needs review.';
  const filterCount = ['source','budget','min-score','evidence'].filter(id => $(`#${id}`).value && $(`#${id}`).value !== '0').length + ($('#stock').value !== 'active' ? 1 : 0) + ($('#photos-only').checked ? 1 : 0);
  $('#filter-count').textContent = filterCount;
  $('#filter-count').hidden = !filterCount;
  $('#grid').innerHTML = page.items.length ? page.items.map((r, cardIndex) => {
    const c = r.candidate, link = originalListingUrl(c), title = c.title.toLowerCase().startsWith(c.brand.toLowerCase() + ' ') ? c.title.slice(c.brand.length).trim() : c.title;
    return `<article class="card">
      <div class="card-visual">${link ? `<a class="image-link" href="${esc(link)}" target="_blank" rel="noopener noreferrer" tabindex="-1">${photo(c, '', 0, cardIndex < 6)}<span class="image-open">Open listing <span aria-hidden="true">↗</span></span></a>` : `<button class="image-link" data-detail="${esc(c.id)}" aria-label="View details for ${esc(c.title)}">${photo(c, '', 0, cardIndex < 6)}</button>`}
      ${evidenceBadge(r)}<button class="save-icon ${r.status === 'liked' ? 'is-saved' : ''}" data-save="${esc(c.id)}" aria-label="${r.status === 'liked' ? 'Unsave' : 'Save'} ${esc(c.title)}" aria-pressed="${r.status === 'liked'}">${r.status === 'liked' ? '♥' : '♡'}</button>
      ${images(c).length ? `<span class="photo-count">${images(c).length} ${images(c).length === 1 ? 'photo' : 'photos'}</span>` : ''}</div>
      <div class="card-body"><div class="card-kicker"><span>${esc(c.brand)}</span><span class="size-tag">${esc(c.size)}</span></div>
      <h2 class="card-title">${link ? `<a class="title-link" href="${esc(link)}" target="_blank" rel="noopener noreferrer" tabindex="-1">${esc(title)}</a>` : `<button class="title-link" data-detail="${esc(c.id)}">${esc(title)}</button>`}</h2>
      <div class="card-price">${price(c)}</div>
      <p class="condition" title="${esc(c.condition)}">${esc(c.condition)}</p>
      ${editorial(r)}
      ${(r.cautions[0] || r.filterReason) ? `<p class="card-caution" title="${esc(r.cautions[0] || r.filterReason)}">${esc(r.cautions[0] || r.filterReason)}</p>` : ''}
      <div class="card-primary">${listingAnchor(c)}<button class="details-button" data-detail="${esc(c.id)}">Details</button></div>
      <div class="card-bottom">${scoreSummary(r)}<span class="card-source">${esc(sourceName(c))}</span><label><input type="checkbox" data-compare="${esc(c.id)}" ${selected.has(c.id) ? 'checked' : ''}> Compare</label>${r.status !== 'new' ? `<span class="review-status">${esc(labels[r.status])}</span>` : ''}</div></div>
    </article>`;
  }).join('') : `<div class="empty"><h2>${data.items.length ? 'No listings in this view' : 'No listings captured yet'}</h2><p>${data.items.length ? 'Change your filters or return to all discoveries.' : 'Refresh after your next crawl.'}</p><button id="empty-reset">Show all discoveries</button></div>`;
  $('#load-more').hidden = !page.hasMore;
  hydrateImages($('#grid'));
  updateTray();
}

const measurementLabels = { chestInches:'Chest · pit to pit', waistInches:'Waist · circumference', inseamInches:'Inseam', riseInches:'Rise', hemInches:'Hem · flat width', thighInches:'Thigh · flat width', kneeInches:'Knee · flat width', lengthInches:'Length', outseamInches:'Outseam', shoulderInches:'Shoulder width', sleeveInches:'Sleeve length' };

function detail(id) {
  const r = item(id); if (!r) return;
  activeId = id; const c = r.candidate, imgs = images(c), link = originalListingUrl(c);
  $('#detail-content').innerHTML = `<div class="detail-gallery"><div id="hero-photo">${photo(c, '', 0, true)}</div><div class="thumbnails">${imgs.map((src, i) => `<button data-photo="${i}" class="${i === 0 ? 'active' : ''}" aria-label="View photo ${i+1}">${photo(c, 'thumbnail-photo', i, false, false)}</button>`).join('')}</div><p class="image-credit">Captured source photography. ${link ? `<a href="${esc(link)}" target="_blank" rel="noopener noreferrer">See all photos at ${esc(sourceName(c))}</a>` : ''}</p></div>
    <div class="detail-copy"><p class="eyebrow">${esc(c.brand)} / ${esc(c.source)}</p><h2>${esc(c.title)}</h2><div class="detail-metrics">${scoreSummary(r)}<div class="detail-price">${price(c)}</div></div><div class="pills"><span>Size ${esc(c.size)}</span><span id="detail-status">${esc(labels[r.status] ?? r.status)}</span></div>
    ${listingAnchor(c, 'original-listing detail-original')}
    ${proxyLink(c)}
    ${(c.alternateListings ?? []).filter(a=>safeUrl(a.url)).length ? `<section><h3>Same seller inventory, other listing routes</h3>${(c.alternateListings ?? []).filter(a=>safeUrl(a.url)).map(a=>`<p><a class="source-link" href="${esc(safeUrl(a.url))}" target="_blank" rel="noopener noreferrer">${esc(a.source)} ↗</a></p>`).join('')}<p class="fine-print">Grouped only when the exact seller inventory code matches.</p></section>` : ''}
    ${isAuction(c) ? `<section><h3>Auction details</h3><div class="auction-cost">Reported bid: ${priceAmount(c.auction?.currentBidJpy)}</div><p>This is not a purchase price. Ends: ${esc(deadline(c))}. ${Number.isInteger(c.auction?.bidCount) ? `${c.auction.bidCount} bids reported.` : 'Bid count unknown.'}</p><div class="auction-cost">Buy now: ${priceAmount(c.auction?.buyNowPriceJpy)}</div><p>Confirm live availability at the source. Proxy fees, shipping and taxes are not included.</p></section>` : ''}
    <p class="gate-note">${r.qualified ? 'Meets current scoring requirements.' : esc(r.filterReason)}</p>
    ${editorial(r, true)}
    <section><h3>The condition</h3><p>${esc(c.condition)}</p></section>
    <section><h3>The fit</h3><dl class="measurements">${Object.entries(c.measurements ?? {}).filter(([,v]) => Number.isFinite(v)).map(([k,v]) => `<div><dt>${esc(measurementLabels[k] ?? k)}</dt><dd>${v}″ <small>${(v*2.54).toFixed(1)} cm</small></dd></div>`).join('') || '<p>No measurements captured.</p>'}</dl></section>
    <section class="assessment" tabindex="-1"><h3>Match score: ${r.score} / 100</h3><p>Heuristic evidence score, not an editorial recommendation or fit probability. Brand and keyword matches can produce a high score for a piece we would still pass on.</p><h3>Positive signals</h3>${list(r.reasons)}<h3>Concerns</h3>${list([...r.cautions, ...(!r.qualified ? [r.filterReason] : [])])}<p>Deal adjustment: ${r.deal.adjustment > 0 ? '+' : ''}${r.deal.adjustment}. Adjusted ranking score: ${r.rankScore}.</p></section>
    <section><h3>Price & costs</h3><p>Deal quality: <strong>${esc(r.deal.label)}</strong></p><div class="cost-summary"><span>${r.deal.costCompleteness === 'listing-only' ? 'Listing price' : 'Captured cost estimate'}</span>${r.deal.costCompleteness === 'listing-only' ? price(c) : priceAmount(r.deal.estimatedTotalCostJpy)}</div>${list(r.deal.caveats ?? [])}<p class="fine-print">${esc(currencyNote())}</p></section>
    <section><h3>Source notes</h3><p>${esc(c.notes || 'No additional notes.')}</p><p>${evidenceBadge(r)}</p><p class="fine-print">Capture’s availability timestamp: ${date(c.availabilityCheckedAt)}. Stock is not independently verified by this browser.</p>${link ? `<a class="source-link" href="${esc(link)}" target="_blank" rel="noopener noreferrer">View original listing ↗</a>` : '<p>Source URL unavailable.</p>'}</section>
    <section class="review-box"><label for="review-note">Your notes</label><textarea id="review-note" maxlength="2000" placeholder="Add a note with your decision"></textarea><div class="review-actions"><button data-review="liked">♡ Save</button><button data-review="watching">Watch</button><button data-review="rejected">Pass</button></div><button class="text-button" data-review="new">Reset to unreviewed</button><p class="fine-print">Decisions and notes sync to your private account.</p></section></div>`;
  $('#review-note').value = r.reviewNote ?? '';
  hydrateImages($('#detail-content'));
  if (!$('#detail').open) $('#detail').showModal();
}

async function review(id, status, note = '') {
  if (saving) return;
  saving = true;
  document.querySelectorAll('[data-review], [data-save]').forEach(b => b.disabled = true);
  try {
    const res = await fetch('/fieldnotes/api/review', { method:'POST', headers:{ 'Content-Type':'application/json', 'X-Review-Token':data.token }, body: JSON.stringify({ id, status, note }) });
    const body = await res.json(); if (!res.ok) throw new Error(body.error);
    item(id).status = status; if (note) item(id).reviewNote = note; render();
    if (activeId === id && $('#detail').open) $('#detail-status').textContent = labels[status];
    toast(status === 'new' ? 'Moved back to unreviewed.' : `${labels[status]} — decision saved to your account.`);
  } catch(e) { toast(`Could not save: ${e.message}`); }
  finally { saving = false; document.querySelectorAll('[data-review], [data-save]').forEach(b => b.disabled = false); }
}

function updateTray() { $('#compare-tray').hidden = !selected.size; $('#compare-count').textContent = `${selected.size} of 3 pieces selected`; $('#compare-open').disabled = selected.size < 2; }
function compare() {
  const rows = [...selected].map(item); if (rows.length < 2) return;
  const fields = [ ['Price · USD', r => plainPrice(r.candidate)], ['Tagged size', r => r.candidate.size], ['Match', r => `${r.score}/100 · ${r.filterReason ?? 'Passes gates'}`], ['Condition', r => r.candidate.condition],
    ...Object.entries(measurementLabels).filter(([k]) => rows.some(r => Number.isFinite(r.candidate.measurements?.[k]))).map(([k,label]) => [label, r => Number.isFinite(r.candidate.measurements?.[k]) ? `${r.candidate.measurements[k]}″` : 'Not captured']),
    ['Fit cautions', r => r.cautions.join('; ') || 'None recorded'], ['Deal quality', r => r.deal.label], ['Review', r => labels[r.status] ?? r.status], ];
  $('#comparison-content').innerHTML = `<table><thead><tr><th scope="col">The pieces</th>${rows.map(r => `<th scope="col">${photo(r.candidate, '', 0, true)}<p class="eyebrow">${esc(r.candidate.brand)}</p><h3>${esc(r.candidate.title)}</h3>${listingAnchor(r.candidate)}</th>`).join('')}</tr></thead><tbody>${fields.map(([label,get]) => `<tr><th scope="row">${esc(label)}</th>${rows.map(r => `<td>${esc(get(r))}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
  hydrateImages($('#comparison-content'));
  $('#comparison').showModal();
}

function reset(all = false) { if (all) { view='all'; if (location.hash !== '#all') history.pushState(null, '', '#all'); } for (const id of ['search','brand','source','size','budget','min-score','stock','evidence']) $(`#${id}`).value = id === 'stock' ? 'active' : ''; $('#photos-only').checked = false; visibleCount = 48; render(); }
document.addEventListener('click', (e) => {
  const el = e.target.closest('button'); if (!el) return;
  if (el.dataset.view) { view = el.dataset.view; history.pushState(null, '', '#' + view); visibleCount = 48; render(); if (el.closest('.more-views') && innerWidth <= 750) el.closest('.more-views').open = false; window.scrollTo({top:0}); }
  if (el.id === 'toggle-filters') { const panel = $('#advanced-filters'); panel.hidden = !panel.hidden; el.setAttribute('aria-expanded', String(!panel.hidden)); }
  if (el.dataset.detail) detail(el.dataset.detail);
  if (el.dataset.score) {
    if (!$('#detail').open || activeId !== el.dataset.score) detail(el.dataset.score);
    $('#detail .assessment').scrollIntoView({ block:'start' });
    $('#detail .assessment').focus({ preventScroll:true });
  }
  if (el.dataset.save) review(el.dataset.save, item(el.dataset.save).status === 'liked' ? 'new' : 'liked');
  if (el.dataset.review) review(activeId, el.dataset.review, $('#review-note').value.trim());
  if (el.dataset.photo) { $('#hero-photo').innerHTML = photo(item(activeId).candidate, '', Number(el.dataset.photo), true, false); hydrateImages($('#hero-photo')); document.querySelectorAll('[data-photo]').forEach(b => b.classList.toggle('active', b===el)); }
  if (el.classList.contains('close')) el.closest('dialog').close();
  if (['clear','empty-reset'].includes(el.id)) reset(el.id === 'empty-reset');
  if (el.id === 'compare-clear') { selected.clear(); render(); }
  if (el.id === 'compare-open') compare();
  if (el.id === 'load-more') { visibleCount += 48; render(); }
  if (el.id === 'refresh') { el.disabled = true; imageLoader.clearFailures(); load().then(() => toast('Collection refreshed.')).catch(e => toast(e.message)).finally(() => el.disabled=false); }
});
document.addEventListener('change', (e) => {
  if (e.target.dataset.compare) {
    const id = e.target.dataset.compare;
    if (e.target.checked && selected.size === 3) { e.target.checked = false; toast('Compare up to three pieces at a time.'); return; }
    e.target.checked ? selected.add(id) : selected.delete(id); updateTray();
  }
});
for (const id of ['search','budget','min-score']) $(`#${id}`).addEventListener('input', render);
for (const id of ['brand','source','size','sort','stock','evidence']) $(`#${id}`).addEventListener('change', () => { visibleCount = 48; render(); });
$('#photos-only').addEventListener('change', () => { visibleCount = 48; render(); });
$('#sort').addEventListener('change', () => { hasSavedSort = true; try { localStorage.setItem('fieldnotes.sort.v2', $('#sort').value); } catch {} });
window.addEventListener('hashchange', () => {
  const next = location.hash.slice(1) || 'latest';
  if (!Object.hasOwn(views, next) || next === view) return;
  view = next; visibleCount = 48; render(); window.scrollTo({top:0});
});
load().catch(e => { $('#result-count').textContent = 'Collection unavailable'; $('#notice').hidden=false; $('#notice').textContent=e.message; });

