import { capturedImageUrls } from './images.js';
import { usdPrice } from './money.js';
const DAY = 24 * 60 * 60 * 1000;

export function auctionPriceSummary(candidate) {
  const auction = candidate?.auction ?? {};
  if (Number.isFinite(auction.currentBidJpy) && auction.currentBidJpy > 0) {
    return { amount: auction.currentBidJpy, caption: 'Reported bid · not final cost' };
  }
  if (Number.isFinite(auction.buyNowPriceJpy) && auction.buyNowPriceJpy > 0) {
    return { amount: auction.buyNowPriceJpy, caption: 'Buy now · confirm live price' };
  }
  return { amount: null, caption: 'Auction price unconfirmed' };
}

export function isUnavailable(row, now = new Date()) {
  const c = row?.candidate ?? row ?? {};
  const end = Date.parse(c.auction?.endsAt);
  return c.availability === 'unavailable' || c.provenance?.indexedUnavailable === true ||
    c.auction?.status === 'ended' || (Number.isFinite(end) && end <= now.getTime());
}

export function isAddedThisWeek(row, now = new Date()) {
  const firstSeen = Date.parse(row?.candidate?.collection?.firstSeenAt);
  return Number.isFinite(firstSeen) && firstSeen >= now.getTime() - 7 * DAY && firstSeen <= now.getTime();
}

export function matchesCollectionView(row, view, now = new Date()) {
  if (view === 'qualified') return row.qualified;
  if (view === 'latest') return row.latestCapture === true;
  if (view === 'stretch') return row.candidate?.provenance?.stretchBudgetCandidate === true;
  if (view === 'auctions') return !!row.candidate?.auction || row.candidate?.dealEvidence?.saleType === 'auction';
  if (view === 'liked' || view === 'watching' || view === 'rejected') return row.status === view;
  if (view === 'added') return isAddedThisWeek(row, now);
  if (view === 'drops') return row?.candidate?.collection?.change === 'price-drop';
  if (view === 'review') return row.candidate?.collection?.status === 'review' && !isUnavailable(row, now);
  if (view === 'unavailable') return isUnavailable(row, now);
  return true;
}

export function evidenceKind(row) {
  const c = row?.candidate ?? row ?? {};
  if (c.provenance?.extraction === 'search-index') return 'search-index';
  if (row.stockVerified !== true) return 'stock-unconfirmed';
  return 'stock-reported';
}

export function filterCollection(items, filters = {}, now = new Date()) {
  const query = String(filters.query ?? '').toLowerCase().trim();
  const maxPrice = filters.maxPrice === '' || filters.maxPrice == null ? Infinity : Number(filters.maxPrice);
  const maxUsd = filters.maxPriceUsd === '' || filters.maxPriceUsd == null ? Infinity : Number(filters.maxPriceUsd);
  const minScore = Number(filters.minScore || 0);
  return items.filter(row => {
    const c = row.candidate ?? {};
    if (!matchesCollectionView(row, filters.view ?? 'all', now)) return false;
    if (filters.view !== 'unavailable' && !['unavailable', 'all'].includes(filters.stock) && isUnavailable(row, now)) return false;
    if (filters.brand && c.brand !== filters.brand) return false;
    if (filters.source && c.source !== filters.source) return false;
    if (filters.size && c.size !== filters.size) return false;
    if (filters.view !== 'unavailable' && filters.stock === 'active' && isUnavailable(row, now)) return false;
    if (filters.stock === 'unavailable' && !isUnavailable(row, now)) return false;
    if (filters.evidence && evidenceKind(row) !== filters.evidence) return false;
    if (filters.photosOnly && !capturedImageUrls(c).length) return false;
    if (row.score < minScore) return false;
    if (maxPrice !== Infinity && (!Number.isFinite(c.priceJpy) || c.priceJpy > maxPrice)) return false;
    if (maxUsd !== Infinity) {
      const p = usdPrice(c, filters.exchangeRates);
      if (p.kind !== 'fixed-price' || !Number.isFinite(p.usd) || p.usd > maxUsd) return false;
    }
    return !query || `${c.brand ?? ''} ${c.title ?? ''} ${c.notes ?? ''} ${c.size ?? ''}`.toLowerCase().includes(query);
  });
}

export function sortCollection(items, sort = 'score', exchangeRates = null) {
  const rows = [...items];
  if (sort === 'editorial') {
    const tier = r => ({recommend: 0, research: 1, pass: 3}[r.normalizedEditorialSummary?.verdict] ?? 2);
    rows.sort((a, b) => tier(a) - tier(b) || (b.rankScore ?? b.score) - (a.rankScore ?? a.score));
  }
  const price = r => {
    if (!exchangeRates) return Number.isFinite(r.candidate?.priceJpy) ? r.candidate.priceJpy : Infinity;
    const p = usdPrice(r.candidate, exchangeRates);
    return p.kind === 'fixed-price' && Number.isFinite(p.usd) ? p.usd : Infinity;
  };
  const time = r => Date.parse(r.candidate?.availabilityCheckedAt) || 0;
  if (sort === 'price') rows.sort((a, b) => price(a) - price(b));
  if (sort === 'price-desc') rows.sort((a, b) => (Number.isFinite(price(b)) ? price(b) : -Infinity) - (Number.isFinite(price(a)) ? price(a) : -Infinity));
  if (sort === 'score') rows.sort((a, b) => b.score - a.score);
  if (sort === 'score-asc') rows.sort((a, b) => a.score - b.score);
  if (sort === 'recent') rows.sort((a, b) => time(b) - time(a));
  if (sort === 'ending') rows.sort((a, b) => (Date.parse(a.candidate?.auction?.endsAt) || Infinity) - (Date.parse(b.candidate?.auction?.endsAt) || Infinity));
  // Rank order comes from the server and preserves wanted-model priority.
  return rows;
}

export function paginateCollection(items, visible = 48) {
  return { items: items.slice(0, visible), hasMore: items.length > visible };
}

