// Use only image URLs that were captured with the listing. In particular, do not
// guess CDN paths, expand URL templates, or send these private records to a proxy.
export function safeImageUrl(value) {
  if (typeof value !== 'string' || !value.trim() || /[{}]|%7[bd]/i.test(value)) return '';
  try {
    const url = new URL(value);
    if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return '';
    const host = url.hostname.toLowerCase().replace(/\.$/, '');
    if (!host || host === 'localhost' || host.endsWith('.localhost') || host.endsWith('.local') ||
      !host.includes('.') || host.includes(':') || /^\d+\.\d+\.\d+\.\d+$/.test(host)) return '';
    // Fragments do not identify a different image resource. Keep query strings:
    // they may select a captured size variant or contain an expiring signature.
    url.hash = '';
    return url.href;
  } catch { return ''; }
}

export function capturedImageUrls(candidate = {}) {
  const array = value => Array.isArray(value) ? value : [];
  const legacy = array(candidate.images).map(value => typeof value === 'string' ? value : value?.url);
  const values = [candidate.imageUrl, ...array(candidate.imageUrls), ...array(candidate.visualEvidence?.imageUrls), ...legacy];
  return [...new Set(values.map(safeImageUrl).filter(Boolean))];
}

function imageQueue(candidate, { index = 0, allowFallbacks = true } = {}) {
  const urls = capturedImageUrls(candidate);
  const start = Number.isInteger(index) && index >= 0 && index < urls.length ? index : 0;
  const indices = allowFallbacks ? [...urls.keys()].slice(start).concat([...urls.keys()].slice(0, start)) : urls.length ? [start] : [];
  return { total: urls.length, entries: indices.map(capturedIndex => ({ url: urls[capturedIndex], capturedIndex })) };
}

/**
 * Create one loader per page session. Failures are kept in memory, never stored
 * in the collection or localStorage. A thumbnail should use allowFallbacks:false
 * so it cannot quietly become a different photograph.
 *
 * attach(img, candidate, {index, allowFallbacks, onState}) returns a cleanup.
 * onState({status, url, capturedIndex, reason, attemptedCount, total}) reports
 * loading / loaded / unavailable. Unavailable reason is 'missing' when no safe
 * capture exists, or 'failed' after every permitted captured URL has failed.
 */
export function createImageLoader() {
  const failed = new Set();
  const bindings = new WeakMap();
  const isFailed = url => failed.has(safeImageUrl(url));
  // An explicit app refresh can retry transient errors. Do not clear failures on
  // ordinary rerenders, or each filter change would repeat broken requests.
  const clearFailures = () => failed.clear();

  function source(candidate, options) {
    return imageQueue(candidate, options).entries.find(entry => !failed.has(entry.url))?.url ?? '';
  }

  function attach(img, candidate, options = {}) {
    bindings.get(img)?.();
    const { entries, total } = imageQueue(candidate, options);
    const attempted = new Set();
    let current = null;
    let stopped = false;
    let loaded = false;

    const report = (status, reason = null) => options.onState?.({
      status, url: current?.url ?? null, capturedIndex: current?.capturedIndex ?? null,
      reason, attemptedCount: attempted.size, total,
    });
    function cleanup() {
      stopped = true;
      img.removeEventListener('load', onLoad);
      img.removeEventListener('error', onError);
      if (bindings.get(img) === cleanup) bindings.delete(img);
    }
    function isCurrent() { return !stopped && current && img.getAttribute('src') === current.url; }
    function onLoad() {
      if (!isCurrent()) return;
      loaded = true;
      img.hidden = false;
      report('loaded');
    }
    function onError() {
      if (!isCurrent() || loaded) return;
      failed.add(current.url);
      advance();
    }
    function advance() {
      if (stopped) return;
      current = entries.find(entry => !failed.has(entry.url) && !attempted.has(entry.url)) ?? null;
      loaded = false;
      if (!current) {
        img.hidden = true;
        img.removeAttribute('src');
        report('unavailable', total ? 'failed' : 'missing');
        cleanup();
        return;
      }
      attempted.add(current.url);
      img.hidden = false;
      report('loading');
      if (img.getAttribute('src') !== current.url) {
        img.setAttribute('src', current.url);
      } else if (img.complete) {
        // An inline image may have finished before hydration attached handlers.
        // Check in a microtask so a later rebind or source change can cancel it.
        const expected = current.url;
        queueMicrotask(() => {
          if (!isCurrent() || current.url !== expected || !img.complete) return;
          if (img.naturalWidth > 0) onLoad(); else onError();
        });
      }
    }

    bindings.set(img, cleanup);
    img.referrerPolicy = 'no-referrer';
    img.addEventListener('load', onLoad);
    img.addEventListener('error', onError);
    advance();
    return cleanup;
  }

  return { source, attach, isFailed, clearFailures };
}

