export function publicUrl(value) {
  try {
    const url = new URL(value);
    return ['http:', 'https:'].includes(url.protocol) && !url.username && !url.password ? url.href : '';
  } catch { return ''; }
}

export function originalListingUrl(candidate) {
  return publicUrl(candidate?.underlyingUrl) || publicUrl(candidate?.auction?.underlyingUrl) || publicUrl(candidate?.url);
}

export function sourceName(candidate) {
  const url = originalListingUrl(candidate);
  const host = url ? new URL(url).hostname.replace(/^www\./, '') : '';
  return ({ 'jp.mercari.com':'Mercari Japan', 'japan.us.mercari.com':'Mercari Japan', '2ndstreet.jp':'2nd Street', 'globalbunjang.com':'Bunjang', 'fruitsfamily.com':'Fruits Family', 'shop.kind.co.jp':'Kindal', 'ragtag.jp':'Ragtag', 'auctions.yahoo.co.jp':'Yahoo Auctions', 'fromjapan.co.jp':'FromJapan', 'item.fril.jp':'Rakuma', 'us.vestiairecollective.com':'Vestiaire', 'item.rakuten.co.jp':'Rakuten', 'ebay.com':'eBay', 'depop.com':'Depop' })[host] || candidate?.source || host || 'Source';
}

