// Display-only price parsing. Never rewrites captured prices, ranking, or shopping state.
const CODES = new Set(('AED AFN ALL AMD ANG AOA ARS AUD AWG AZN BAM BBD BDT BGN BHD BIF BMD BND BOB BRL BSD BTN BWP BYN BZD CAD CDF CHF CLP CNY COP CRC CUP CVE CZK DJF DKK DOP DZD EGP ERN ETB EUR FJD FKP GBP GEL GHS GIP GMD GNF GTQ GYD HKD HNL HTG HUF IDR ILS INR IQD IRR ISK JMD JOD JPY KES KGS KHR KMF KPW KRW KWD KYD KZT LAK LBP LKR LRD LSL LYD MAD MDL MGA MKD MMK MNT MOP MRU MUR MVR MWK MXN MYR MZN NAD NGN NIO NOK NPR NZD OMR PAB PEN PGK PHP PKR PLN PYG QAR RON RSD RUB RWF SAR SBD SCR SDG SEK SGD SHP SLE SOS SRD SSP STN SVC SYP SZL THB TJS TMT TND TOP TRY TTD TWD TZS UAH UGX USD UYU UZS VES VND VUV WST XAF XCD XOF XPF YER ZAR ZMW ZWG').split(' '));
const SYMBOLS = { 'US$': 'USD', 'US $': 'USD', 'A$': 'AUD', 'AU$': 'AUD', 'C$': 'CAD', 'CA$': 'CAD', 'NZ$': 'NZD', 'HK$': 'HKD', 'S$': 'SGD', 'NT$': 'TWD', 'CN¥': 'CNY', 'RMB': 'CNY', '¥': 'JPY', '円': 'JPY', '₩': 'KRW', '원': 'KRW', '€': 'EUR', '£': 'GBP', '$': null };
const codePattern = [...CODES].join('|');
const markerPattern = `(?:US\\s?\\$|AU\\$|A\\$|CA\\$|C\\$|NZ\\$|HK\\$|S\\$|NT\\$|CN¥|RMB|¥|円|₩|원|€|£|\\$|(?<![A-Za-z])(?:${codePattern})(?![A-Za-z]))`;
const numberPattern = '[0-9]+(?:[.,\\u00a0\\u202f \'’][0-9]+)*';
const positive = value => typeof value === 'number' && Number.isFinite(value) && value > 0;
const DOLLAR_CODES = new Set('USD AUD CAD NZD HKD SGD TWD MXN XCD BSD BBD BZD KYD GYD JMD LRD NAD SBD SRD FJD TTD'.split(' '));
const isReference = text => /参考|定価|\breference(?: price| retail)?\b|\bretail(?: price)?\b|\bMSRP\b|\bRRP\b/i.test(text);

function amountNumber(value) {
  if (positive(value)) return value;
  if (typeof value !== 'string') return null;
  let text = value.normalize('NFKC').trim();
  if (!/^\d+(?:[., '\u2019]\d+)*$/.test(text)) return null;
  // Spaces/apostrophes are accepted only as full three-digit grouping.
  if (/[ '\u2019]/.test(text)) {
    if (!/^\d{1,3}(?:[ '\u2019]\d{3})+(?:[.,]\d{1,2})?$/.test(text)) return null;
    text = text.replace(/[ '\u2019]/g, '');
  }
  if (text.includes(',') && text.includes('.')) {
    const decimal = text.lastIndexOf(',') > text.lastIndexOf('.') ? ',' : '.';
    const group = decimal === ',' ? '.' : ',';
    const escaped = group === '.' ? '\\.' : ',';
    if (!new RegExp(`^\\d{1,3}(?:${escaped}\\d{3})*\\${decimal}\\d{1,2}$`).test(text)) return null;
    text = text.split(group).join('').replace(decimal, '.');
  } else if (/[.,]/.test(text)) {
    const separator = text.includes(',') ? ',' : '.';
    const parts = text.split(separator);
    if (parts.length === 2 && parts[1].length <= 2) text = `${parts[0]}.${parts[1]}`;
    else if (parts[0].length <= 3 && parts.slice(1).every(part => part.length === 3)) text = parts.join('');
    else return null;
  }
  const number = Number(text);
  return positive(number) ? number : null;
}

function isoCurrency(value) {
  const code = typeof value === 'string' ? value.trim().toUpperCase() : '';
  return CODES.has(code) ? code : null;
}

function capturedCurrency(candidate) {
  const provenance = candidate?.provenance ?? {};
  const evidence = provenance.evidence ?? {};
  for (const value of [candidate?.currency, candidate?.priceCurrency, provenance.currency, provenance.nativeCurrency, provenance.priceCurrency, evidence.currency, evidence.nativeCurrency, evidence.priceCurrency]) {
    const code = isoCurrency(value);
    if (code) return code;
  }
  // This establishes currency only; amounts are never taken from narrative evidence.
  const codes = typeof evidence.price === 'string' ? [...evidence.price.matchAll(new RegExp(`\\b(${codePattern})\\b`, 'gi'))].map(match => match[1].toUpperCase()) : [];
  if (new Set(codes).size === 1) return codes[0];
  // These are explicitly US marketplace captures, rather than global-marketplace locales.
  if (/^mercari-us$/i.test(candidate?.source ?? '') || /^the[- ]realreal$/i.test(candidate?.source ?? '')) return 'USD';
  return null;
}

function currencyFor(markers, candidate) {
  const explicit = markers.map(marker => isoCurrency(marker) ?? SYMBOLS[marker.toUpperCase().replace(/\s+/g, ' ')]).filter(Boolean);
  const currencies = [...new Set(explicit)];
  if (currencies.length > 1) return null;
  if (currencies.length) return currencies[0];
  const captured = markers.includes('$') ? capturedCurrency(candidate) : null;
  return DOLLAR_CODES.has(captured) ? captured : null;
}

function parseOriginal(original, candidate) {
  if (original && typeof original === 'object' && !Array.isArray(original)) {
    const amount = amountNumber(original.amount);
    const currency = isoCurrency(original.currency);
    return { amount, currency, kind: original.kind === 'reference' ? 'reference' : 'fixed-price', reason: !amount ? 'Captured amount is missing or invalid.' : !currency ? 'Captured currency is unconfirmed.' : null };
  }
  if (typeof original !== 'string' || !original.trim()) return { amount: null, currency: null, kind: 'unknown', reason: 'No captured price.' };
  let text = original.normalize('NFKC').trim();
  const kind = isReference(text) ? 'reference' : 'fixed-price';
  // Audited collector annotations contain historical exchange rates and dates, not extra asks.
  text = text.replace(/\([^()]*(?:JPY estimate|conversion|native displayed currency|native currency|independently observed|reduced from)[^()]*\)/gi, '').trim();
  const expression = new RegExp(`(${markerPattern})\\s*(${numberPattern})(?:\\s*(${markerPattern}))?|(${numberPattern})\\s*(${markerPattern})`, 'gi');
  const matches = [...text.matchAll(expression)];
  if (!matches.length) return { amount: null, currency: null, kind: 'unknown', reason: 'No unambiguous captured amount and currency.' };
  const parsed = matches.map(match => ({
    amount: amountNumber(match[2] ?? match[4]),
    currency: currencyFor(match[1] ? [match[1], match[3]].filter(Boolean) : [match[5]], candidate),
    index: match.index,
    end: match.index + match[0].length,
  }));
  // A separately labelled shipping charge or previous ask is not the current item price.
  const primary = parsed[0];
  if (/[-−]\s*$/.test(text.slice(0, primary.index))) return { amount: null, currency: null, kind: 'unknown', reason: 'Captured amount is missing or invalid.' };
  const extra = parsed.slice(1);
  const extrasAreAnnotations = extra.every((match, index) => {
    const before = text.slice(parsed[index].end, match.index);
    const after = text.slice(match.end, parsed[index + 2]?.index ?? text.length);
    return /reduced from|was\s*$/i.test(before) || /shipping|送料/i.test(after);
  });
  if (extra.length && !extrasAreAnnotations) return { amount: null, currency: null, kind: 'unknown', reason: 'Captured price contains a range or multiple amounts/currencies.' };
  const residue = `${text.slice(0, primary.index)} ${text.slice(primary.end, extra[0]?.index ?? text.length)}`;
  if (/\d/.test(residue) && !/^\s*\d+(?:[.,]\d+)?%\s*OFF\s*$/i.test(text.slice(0, primary.index))) return { amount: null, currency: null, kind: 'unknown', reason: 'Captured price contains another unclassified amount.' };
  return { amount: primary.amount, currency: primary.currency, kind, reason: !primary.amount ? 'Captured amount is missing or invalid.' : !primary.currency ? 'Captured currency is unconfirmed.' : null };
}

function originalTextFor(value) {
  if (typeof value === 'string') return value;
  if (value && typeof value === 'object') return `${value.amount ?? ''} ${value.currency ?? ''}`.trim() || null;
  return null;
}

function isAuction(candidate) {
  return !!candidate?.auction || candidate?.saleType === 'auction' || candidate?.dealEvidence?.saleType === 'auction' || /auctions\.yahoo\.co\.jp/.test(candidate?.url ?? '') || /\b(?:current bid|reported bid|buy (?:it )?now)\b|現在(?:価格)?\s*\d|即決\s*\d/i.test(candidate?.priceOriginal ?? '');
}

function typedAuctionPrice(candidate) {
  if (typeof candidate.priceOriginal !== 'string') return null;
  const text = candidate.priceOriginal.normalize('NFKC');
  const labels = [...text.matchAll(/\b(current\s+bid|reported\s+bid|buy\s+(?:it\s+)?now)\b|現在(?:価格)?|即決/gi)];
  const prices = labels.flatMap((label, index) => {
    // A collector's statement that a number is NOT a bid must not create one.
    if (/\b(?:not|no)\s+(?:a\s+)?$/i.test(text.slice(0, label.index))) return [];
    const start = label.index + label[0].length;
    const segment = text.slice(start, labels[index + 1]?.index ?? text.length)
      .replace(/^\s*(?:[:：]|also\b)\s*/i, '').replace(/[\s;；／/]+$/, '').trim();
    const parsed = parseOriginal(segment, candidate);
    if (!positive(parsed.amount) || !parsed.currency || parsed.kind !== 'fixed-price') return [];
    return [{ amount: parsed.amount, currency: parsed.currency,
      kind: /^(?:buy|即決)/i.test(label[0]) ? 'auction-buy-now' : 'auction-bid' }];
  });
  for (const kind of ['auction-bid', 'auction-buy-now']) {
    const options = prices.filter(price => price.kind === kind);
    if (options.length && new Set(options.map(price => `${price.currency}:${price.amount}`)).size === 1) return options[0];
  }
  return null;
}

export function capturedPrice(candidate = {}) {
  candidate ??= {};
  const originalText = originalTextFor(candidate.priceOriginal);
  if (isAuction(candidate)) {
    const auction = candidate.auction ?? {};
    if (positive(auction.currentBidJpy)) return { amount: auction.currentBidJpy, currency: 'JPY', kind: 'auction-bid', originalText };
    if (positive(auction.buyNowPriceJpy)) return { amount: auction.buyNowPriceJpy, currency: 'JPY', kind: 'auction-buy-now', originalText };
    const legacy = typedAuctionPrice(candidate);
    if (legacy) return { ...legacy, originalText };
    return { amount: null, currency: null, kind: 'unknown', originalText, reason: 'Auction bid and buy-now price are unconfirmed.' };
  }
  const parsed = parseOriginal(candidate.priceOriginal, candidate);
  if (parsed.kind === 'reference') return { ...parsed, originalText };
  // Explicit foreign asks avoid round-tripping old estimated JPY values.
  if (parsed.amount && parsed.currency && parsed.currency !== 'JPY') return { ...parsed, originalText };
  if (positive(candidate.priceJpy)) return { amount: candidate.priceJpy, currency: 'JPY', kind: 'fixed-price', originalText,
    ...(parsed.currency === 'JPY' || !originalText ? {} : { reason: 'Uses the captured JPY value; original currency or amount is unconfirmed.' }) };
  if (parsed.amount && parsed.currency) return { ...parsed, originalText };
  return { ...parsed, amount: null, currency: null, kind: 'unknown', originalText };
}

export function usdPrice(candidate, exchangeRates = {}) {
  const captured = capturedPrice(candidate);
  const failed = reason => ({ ...captured, usd: null, estimated: false, rateDate: null, conversionReason: reason });
  if (!positive(captured.amount) || !captured.currency) return failed(captured.reason ?? 'Captured price is unconfirmed.');
  if (captured.currency === 'USD') return { ...captured, usd: captured.amount, estimated: false, rateDate: null, conversionReason: null };
  if (exchangeRates?.base !== 'USD') return failed('USD exchange rates are unavailable.');
  const rate = exchangeRates.rates?.[captured.currency];
  if (!positive(rate)) return failed(`No USD exchange rate is available for ${captured.currency}.`);
  const usd = captured.amount / rate;
  if (!positive(usd)) return failed('The converted price is invalid.');
  return { ...captured, usd, estimated: true, rateDate: typeof exchangeRates.date === 'string' ? exchangeRates.date : null, conversionReason: null };
}

export function formatMoney(amount, currency, options = {}) {
  if (!positive(amount) || !isoCurrency(currency)) return null;
  return new Intl.NumberFormat('en-US', { style: 'currency', currency, currencyDisplay: 'code', maximumFractionDigits: 2, ...options }).format(amount);
}
